This program creates a similar zombie thread but that does not work the same way. Killing it does not trigger reboot. Killing kdeconnectd still triggers, despite of the presence of this additional zombie.

```
#include <ctype.h>
#include <errno.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

static void hang(void) {
        struct timespec ts = {100, 0};

        for(;;)
                nanosleep(&ts, NULL);
}

static void *thread_start(void *arg) {
        hang();
        return NULL;
}

int main(void) {
        pid_t pid;
        int r;
        pthread_t thread_id;

        pid = fork();
        if (pid > 0) {
                return 0;
        }
        (void)setsid();
        pid = fork();
        if (pid > 0) {
                hang();
                return 0;
        } else if (pid == 0) {
                r = pthread_create(&thread_id, NULL, thread_start, NULL);
                if (r != 0)
                        perror("pthread_create");
                pthread_exit(NULL);
        } else {
                perror("fork");
                return -1;
        }
        return 0;
}

```
